UInt16 speed_get( void )
{
	UInt16 ret_val = 0;
	
	if( speed_value != 0 )
	{
			//return (UInt16)( 60 * ( TACHO_CONSTANT /tacho_value) );
		ret_val = (UInt16)(4*( (15 * TACHO_CONSTANT)/ speed_value ));
		return ret_val;
	}
	else
		return (0);

}

